hadiths.text_ar:
حَدَّثَنَا  /26  أَحْمَد بْن مُحَمَّد بْن سَعِيد المَرْوَزِيّ L10298  /26  ، حَدَّثَنَا  /26  عُمَر بْن شَبَّة L5964  /26  ، حَدَّثَنَا  /26  أَبُو صَفْوَان نصر بْن قديد بْن يَسَار L-10000  /26  ، حَدَّثَنَا  /26  أَبُو عَمْرو بْن حُمَيد L25650  /26  السغاني ، عَنْ  /26  عَبْد الحميد بْن أَنَس L20406  /26  ، عَنْ  /26  نصر بْن يَسَار L-10000  /26  ، عَنْ  /26  عكرمة  /26  ، /27 عَنِ  /93  ابْنِ عَبَّاسٍ L4883  /93  ، مَرْفُوعًا : " /20 مَنْ أَنْعَمَ عَلَى عَبْدٍ نِعْمَةً فَلَمْ يَشْكُرْهُ فَدَعَا عَلَيْهِ اسْتُجِيبَ لَهُ " /27 . نصر بْن قديد كذاب ، ونصر بْن يَسَار كَانَ أميرًا عَلَى خُراسان ، وأَبُو عَمْرو وعبد الحميد مَجْهُولان ، والحديث غَيْر محفوظ . قاله العُقَيْليّ . قُلْتُ : أَخْرَجَهُ  /26  الْحَسَن بْن بدر  /26  ، عَنْ خبره ما رواه  /26  الخلفاء  /26  ، حَدَّثَنَا  /26  مُحَمَّد بْن القاسم البزار  /26  ، حَدَّثَنَا  /26  ابْن هَارُون الهاشمي  /26  ، حَدَّثَنَا  /26  أَبُو عوانة مُحَمَّد بْن الْحَسَن  /26  ، حَدَّثَنَا  /26  الْعَبَّاس بْن بَكَّار الضَّبِّيّ  /26  ، حَدَّثَنَا  /26  أَبُو بَكْر الهذلي  /26  بِهِ ، فزالت تهمة  /26  جَعْفَر بْن عَبْد الواحد  /26  ، وأخرجه الشيرازي فِي الألقاب  /26  منْ طريق سلمويه النَّحْويّ  /26  ، عَنْ  /26  عَبْد اللَّه بْن الْمُبَارَك  /26  ، عَنْ    @ 2 : 355 @    /26  نصر بْن يَسَار  /26  ، عَنْ  /26  عكرمة  /26  ، عَنِ  /26  ابْن عَبَّاس  /26  ، فزالت تهمة  /26  نصر بْن قديد  /26  ، وشيخه ،  /26  وشيخ  /26  شيخه وَفِي آخره  /26  زيادة  /26  ، ثُمّ قَالَ  /26  نصر بْن يَسَار  /26  : اللهم إنك تعلم أني أنعمت  /26  عَلَى آل بسام نعمة  /26  فلم يشكروها لي ، اللَّهُمَّ فأهرق دماءهم . قَالَ  /26  عَبْد اللَّه بْن الْمُبَارَك  /26  : فَمَا حال عليهم الحول ومنهم  /26  عين  /26  تطرف . وأخرجه  /26  الحاكم  /26  فِي تاريخ نَيْسابور . حَدَّثَنَا  /26  أَحْمَد بْن حمدان الصَّيْرفيّ  /26  ، حَدَّثَنَا  /26  أَبُو رجاء مُحَمَّد بْن حمديه  /26  السخي ، حَدَّثَنَا  /26  أَحْمَد بْن جميل أَبُو حاتم  /26  ، حَدَّثَنَا  /26  عَبْد الْعَزِيز بْن أَبِي رزمة  /26  ، عَنِ  /26  ابْن الْمُبَارَك  /26  ، سَمِعْتُ  /26  نصر بْن سيار المَرْوَزِيّ  /26  ، أَنْبَأَنَا  /26  الليث  /26  والي خراسان عَلَى منبر مَرْو ، يَقُولُ : حَدَّثَنِي  /26  عكرمة  /26  فرواه ، فَذَكَرَه بلفظ منْ أسدى  /26  إِلَى  /26  قوم  /26  نعمة  /26  فلم يقبلوا بالشكر ، ثُمّ دعا عليهم استجيب لَهُ فيهم " . قَالَ  /26  ابْن الْمُبَارَك  /26  لما رَوَى  /26  نصر  /26  هَذَا الْحَدِيث رفع يديه ، وقَالَ : اللَّهُمَّ أنَّكَ تَعْلَم إني أسديت  /26  إِلَى آل بسام خيرًا  /26  فلم يقبلوه بالشكر فاجعل موتهم قتلا . قَالَ : فسمعت أنهم قتلوا فِي مرحلة واحدة  /26  سبعين رَجُلًا  /26   * 
@E876 
$2328  2328 /2

